def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        if hp <= 2 or no_water >= 1:
            return min(budget, 50)
        if supply >= 22:
            return min(budget, 18)
        return min(budget, 28)

    prev_bids = []
    distressed_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) > budget:
            rich_opp += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            distressed_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))
            if prev.get('status') == 'lost' and opp.get('hp', 10) <= 3:
                distressed_opp += 1

    high_supply = supply >= 22
    low_supply = supply <= 17

    if hp <= 1:
        base = 68
    elif hp <= 2 or no_water >= 2:
        base = 62
    elif hp <= 4 or no_water >= 1:
        base = 48
    else:
        base = 34 if high_supply else 42

    if low_supply:
        base += 8
    elif high_supply:
        base -= 6

    if distressed_opp > 0:
        base += 4
    if rich_opp >= max(1, len(alive) // 2):
        base += 3

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        if hp <= 2 or no_water >= 1:
            target = highest_prev + 2
            bid = max(base, target)
        else:
            if highest_prev >= 60:
                bid = min(base, 32 if high_supply else 38)
            elif highest_prev >= 45:
                bid = max(base, avg_prev + 1.5)
            else:
                bid = max(base, highest_prev + 1)
    else:
        bid = base

    remaining_days = max(0, 10 - day)
    reserve = 0
    if remaining_days > 0:
        reserve = remaining_days * 8
    max_affordable = max(0, budget - reserve)

    if hp <= 2 or no_water >= 2:
        max_affordable = budget
    elif hp <= 4 and no_water >= 1:
        max_affordable = max(max_affordable, budget * 0.75)

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0, bid)

    if bid < 1 and budget >= 1 and (hp <= 4 or no_water >= 1):
        bid = 1

    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    alive = [o for o in opponents_status.values() if o['alive']]
    if not alive:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Look at yesterday's highest bid from opponents
    yesterday_bids = []
    for opp in alive:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev = max(yesterday_bids)
        # If we are very low on hp, bid aggressively
        if my_status['hp'] <= 2:
            target = min(my_status['budget'], max(DAILY_SALARY * 0.9, highest_prev + 2))
        else:
            target = min(my_status['budget'], highest_prev + 1.5)
        return target

    # No history: conservative bid
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.85)
    return min(my_status['budget'], DAILY_SALARY * 0.4)
